        $out->{'super_reduced'} = $this->toSuperReduced();
        return $out;
    }

    /**
     * @param stdClass $obj
     * @return Rates
     * @throws Exception
     */
    public static function from(stdClass $obj): Rates {
        if (!property_exists($obj, 'standard')) {
            throw new Exception("Missing required property");
        }
        return new Rates(
         Rates::fromParking($obj->{'parking'})
        ,Rates::fromReduced($obj->{'reduced'})
        ,Rates::fromReduced1($obj->{'reduced1'})
        ,Rates::fromReduced2($obj->{'reduced2'})
        ,Rates::fromStandard($obj->{'standard'})
        ,Rates::fromSuperReduced($obj->{'super_reduced'})
        );
    }

    /**
     * @return Rates
     */
    public static function sample(): Rates {
        return new Rates(
         Rates::sampleParking()
        ,Rates::sampleReduced()
        ,Rates::sampleReduced1()
        ,Rates::sampleReduced2()
        ,Rates::sampleStandard()
        ,Rates::sampleSuperReduced()
        );
    }
}
